# Problem: longest palindromic substring.
# Expand around each center (both odd and even centers). O(n^2) but simple and correct.
def longest_palindrome(s):
    if not s:
        return ''
    def expand(lo, hi):
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        return s[lo+1:hi]  # one past the broken boundary on each side
    best = ''
    for i in range(len(s)):
        for p in (expand(i, i), expand(i, i+1)):
            if len(p) > len(best):
                best = p
    return best
```

