# Problem: is n exactly k*k for some integer k?
# Use integer sqrt logic; check the result squared equals n.
def valid_perfect_square(n):
    if n < 0:
        return False
    if n < 2:
        return True
    lo, hi = 1, n // 2
    while lo <= hi:
        mid = (lo + hi) // 2
        sq = mid * mid
        if sq == n:
            return True
        elif sq < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return False
```

