# Problem: detect duplicates within window of size k.
# Sliding window of seen elements; remove the one falling out as we slide.
def contains_nearby_duplicate(nums, k):
    if k <= 0:
        return False
    seen = set()
    for i, x in enumerate(nums):
        if x in seen:
            return True
        seen.add(x)
        if len(seen) > k:
            seen.remove(nums[i - k])  # drop the one going out of window
    return False
```

