# Problem: intersection of two sorted lists, deduped.
# Two-pointer walk: equal -> emit (skipping run), smaller pointer advances.
def intersection_sorted(a, b):
    i = j = 0
    result = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            if not result or result[-1] != a[i]:
                result.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return result
